inputs.script:
$ErrorActionPreference = 'Stop'
$matches = @(Get-ChildItem -LiteralPath $env:SYSTEM_DEFAULTWORKINGDIRECTORY -Recurse -File -Filter 'release_reporting.py' | Where-Object { $_.Directory.Name -eq 'tools' })
if ($matches.Count -ne 1) { throw 'Expected one packaged release_reporting.py. Rebuild the CI artifact with reporting dependencies.' }
& python $matches[0].FullName publish
if ($LASTEXITCODE -ne 0) { throw "Evidence publication failed with exit code $LASTEXITCODE" }

